import { test, expect } from '@playwright/test';
import { prepareReadOnly, dismissPopups, expectRtlDocument, LOAD } from './rtl-dir.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test.describe('html dir=rtl — живой DOM (user)', () => {
  test('/addbusiness шаг 1: <html lang="he" dir="rtl">, body direction rtl #9c4736 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context, { allowTokenRefresh: true });
    await dismissPopups(page);
    await page.goto('/addbusiness');
    await expect(page.getByPlaceholder('יופיע ככותרת של המודעה שלך'), 'шаг 1 мастера (поле заголовка) — сессия user действует').toBeVisible(LOAD);
    expect(new URL(page.url()).pathname, 'без перехода на /auth').toBe('/addbusiness');
    await expectRtlDocument(page, '/addbusiness');
  });
});
